CREATE TABLE IF NOT EXISTS schema_migrations (version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id uuid PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE wallets (address text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id));
CREATE TABLE auth_challenges (id uuid PRIMARY KEY, flow_hash text NOT NULL, input jsonb NOT NULL, expires_at timestamptz NOT NULL, consumed_at timestamptz);
CREATE TABLE sessions (token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), expires_at timestamptz NOT NULL);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE watchlists (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), name text NOT NULL, items jsonb NOT NULL DEFAULT '[]', updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE investigations (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), name text NOT NULL, pool_address text NOT NULL, notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notification_preferences (user_id uuid PRIMARY KEY REFERENCES users(id), in_app boolean NOT NULL DEFAULT true);
CREATE TABLE provider_checkpoints (cluster text NOT NULL, provider text NOT NULL, stage text NOT NULL, slot numeric(20,0) NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(cluster,provider,stage));
CREATE TABLE coverage_intervals (id bigserial PRIMARY KEY, cluster text NOT NULL, start_slot numeric(20,0) NOT NULL, end_slot numeric(20,0), status text NOT NULL, detail text NOT NULL, observed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE chain_observations (id text PRIMARY KEY, cluster text NOT NULL, signature text NOT NULL, slot numeric(20,0) NOT NULL, block_hash text NOT NULL, provider text NOT NULL, commitment text NOT NULL, raw jsonb NOT NULL, status text NOT NULL DEFAULT 'canonical', received_at timestamptz NOT NULL DEFAULT now(), UNIQUE(cluster,signature,slot,block_hash,provider,commitment));
CREATE INDEX observations_signature ON chain_observations(cluster,signature);
CREATE TABLE canonical_events (event_id text PRIMARY KEY, cluster text NOT NULL, pool_address text NOT NULL, kind text NOT NULL, slot numeric(20,0) NOT NULL, signature text NOT NULL, instruction_path jsonb NOT NULL, ordinal integer NOT NULL, commitment text NOT NULL, observation_id text NOT NULL REFERENCES chain_observations(id), payload jsonb NOT NULL, active boolean NOT NULL DEFAULT true, UNIQUE(cluster,signature,instruction_path,ordinal));
CREATE INDEX events_pool_slot ON canonical_events(cluster,pool_address,slot);
CREATE TABLE pools (cluster text NOT NULL, address text NOT NULL, base_mint text, quote_mint text, config_address text, creator text, lifecycle text NOT NULL, state jsonb NOT NULL DEFAULT '{}', slot numeric(20,0) NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(cluster,address));
CREATE TABLE account_snapshots (id text PRIMARY KEY, cluster text NOT NULL, address text NOT NULL, slot numeric(20,0) NOT NULL, write_version text, payload_hash text NOT NULL, payload jsonb NOT NULL, UNIQUE(cluster,address,slot,payload_hash));
CREATE TABLE signals (id text PRIMARY KEY, cluster text NOT NULL, pool_address text NOT NULL, rule_id text NOT NULL, rule_version text NOT NULL, severity text NOT NULL, status text NOT NULL DEFAULT 'active', payload jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE signal_revisions (id bigserial PRIMARY KEY, signal_id text NOT NULL REFERENCES signals(id), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outbox_events (id bigserial PRIMARY KEY, user_id uuid REFERENCES users(id), topic text NOT NULL, entity_id text NOT NULL, payload jsonb NOT NULL, dedup_key text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX outbox_visibility ON outbox_events(user_id,id);
CREATE TABLE processing_jobs (id uuid PRIMARY KEY, kind text NOT NULL, dedup_key text NOT NULL UNIQUE, payload jsonb NOT NULL, status text NOT NULL DEFAULT 'pending', attempts integer NOT NULL DEFAULT 0, available_at timestamptz NOT NULL DEFAULT now(), lease_until timestamptz, lease_token uuid, last_error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX jobs_claim ON processing_jobs(status,available_at,lease_until);
CREATE TABLE ai_assessments (cache_key text PRIMARY KEY, model text NOT NULL, mode text NOT NULL, result jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE fixture_snapshots (cluster text PRIMARY KEY, payload jsonb NOT NULL);
